draw:
var k = 8.99e9;
var R = p.R, Q = p.Q * 1e-9, z = p.z;
var f = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = f;
ctx.lineWidth = 2;

// layout
var axY = H * 0.34;
var x0 = W * 0.12;              // ring centre on screen
var mPerPx = 0.45 / (W * 0.72); // metres per pixel along the axis
var ringPx = R / mPerPx * 0.55; // vertical half-height of the ring ellipse

// axis line
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0 - W * 0.06, axY); ctx.lineTo(W - 14, axY); ctx.stroke();

// the ring, seen edge-on-ish as an ellipse
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.ellipse(x0, axY, Math.max(4, ringPx * 0.34), Math.max(6, ringPx), 0, 0, Math.PI * 2);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("ring, charge Q, radius R", x0 - 10, axY - Math.max(6, ringPx) - 10);

// probe point P at distance z
var px = x0 + z / mPerPx;
if (px > W - 24) px = W - 24;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, axY, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("P", px - 4, axY + 20);

// z measurement
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, axY + 34); ctx.lineTo(px, axY + 34); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, axY + 30); ctx.lineTo(x0, axY + 38); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, axY + 30); ctx.lineTo(px, axY + 38); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("z = " + z.toFixed(2) + " m", (x0 + px) / 2 - 24, axY + 52);

// two sample elements and their dE vectors, to show the cancelling
var top = axY - Math.max(6, ringPx), bot = axY + Math.max(6, ringPx);
var pairs = [top, bot];
for (var i = 0; i < 2; i++) {
  var ey = pairs[i];
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x0, ey); ctx.lineTo(px, axY); ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x0, ey, 3, 0, Math.PI * 2); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("dq", x0 - 24, top + 4);
ctx.fillText("dq", x0 - 24, bot + 4);

// field value and arrow
function Efield(zz) { return k * Q * zz / Math.pow(zz * zz + R * R, 1.5); }
var E = Efield(z);
var zpk = R / Math.SQRT2;
var Emax = Efield(zpk);
var arrow = 18 + 46 * (Emax > 0 ? E / Emax : 0);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(px, axY); ctx.lineTo(px + arrow, axY); ctx.stroke();
ctx.beginPath();
ctx.moveTo(px + arrow, axY); ctx.lineTo(px + arrow - 8, axY - 5); ctx.lineTo(px + arrow - 8, axY + 5);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("E on axis", px + 6, axY - 12);

// graph of E against z
var gy = H * 0.92, gx0 = 34, gx1 = W - 14, gtop = H * 0.58;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx0, gtop); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("E", gx0 - 16, gtop + 10);
ctx.fillText("z", gx1 - 10, gy + 16);

var zmax = 0.45;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 160; j++) {
  var zz = zmax * j / 160;
  var gxp = gx0 + (gx1 - gx0) * zz / zmax;
  var gyp = gy - (gy - gtop) * (Emax > 0 ? Efield(zz) / Emax : 0) * 0.92;
  if (j === 0) ctx.moveTo(gxp, gyp); else ctx.lineTo(gxp, gyp);
}
ctx.stroke();

// peak marker
var pkx = gx0 + (gx1 - gx0) * Math.min(zpk, zmax) / zmax;
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(pkx, gy); ctx.lineTo(pkx, gtop + 4); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("z = R/sqrt(2)", Math.min(pkx + 4, gx1 - 78), gtop + 14);

// current z marker on the graph
var curx = gx0 + (gx1 - gx0) * Math.min(z, zmax) / zmax;
var cury = gy - (gy - gtop) * (Emax > 0 ? E / Emax : 0) * 0.92;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(curx, cury, 4, 0, Math.PI * 2); ctx.fill();

out.note = "E = " + E.toFixed(1) + " N/C   |   peak at z = " + zpk.toFixed(3) +
  " m, where E = " + Emax.toFixed(1) + " N/C";

var f = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = f;

var cx = W * 0.30;          // rod sits on this vertical line
var cy = H * 0.50;          // midpoint of the rod
var half = H * 0.36;        // half-length of the rod on screen
var px = W * 0.72, py = cy; // field point P

// the rod
ctx.strokeStyle = C.accent;
ctx.lineWidth = 4;
ctx.beginPath(); ctx.moveTo(cx, cy - half); ctx.lineTo(cx, cy + half); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("rod, length L, charge per length lambda", 10, cy - half - 12);

// perpendicular bisector
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(px + 30, cy); ctx.stroke();
ctx.setLineDash([]);

// the element at +x and its mirror at -x
var ey = cy - half * 0.55, my = cy + half * 0.55;
ctx.fillStyle = C.figure;
ctx.fillRect(cx - 4, ey - 5, 8, 10);
ctx.fillRect(cx - 4, my - 5, 8, 10);
ctx.fillStyle = C.ink;
ctx.fillText("dq = lambda dx", cx - 108, ey + 4);
ctx.fillText("mirror element", cx - 100, my + 4);

// the point P
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, py, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("P", px + 6, py + 18);

// r lines
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(cx, ey); ctx.lineTo(px, py); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, my); ctx.lineTo(px, py); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("r = sqrt(x^2 + y^2)", (cx + px) / 2 - 46, ey + (py - ey) / 2 - 6);

// dE vectors at P, pointing away from each element
function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 9 * Math.cos(a - 0.4), y2 - 9 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 9 * Math.cos(a + 0.4), y2 - 9 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}
var len = 62;
var a1 = Math.atan2(py - ey, px - cx);
var a2 = Math.atan2(py - my, px - cx);
arrow(px, py, px + len * Math.cos(a1), py + len * Math.sin(a1), C.accent);
arrow(px, py, px + len * Math.cos(a2), py + len * Math.sin(a2), C.accent);
ctx.fillStyle = C.ink;
ctx.fillText("dE from the top element", px + 16, py + len * Math.sin(a1) - 6);
ctx.fillText("dE from its mirror", px + 16, py + len * Math.sin(a2) + 16);

// the surviving horizontal sum
arrow(px, py, px + 2 * len * Math.cos(a1), py, C.figure);
ctx.fillStyle = C.ink;
ctx.fillText("y-parts cancel; only this survives", px - 60, py - 86);

// angle theta between r and the bisector
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.arc(px, py, 30, Math.PI + a1, Math.PI, false); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("theta", px - 52, py - 14);

// distance y
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(cx, cy + half + 18); ctx.lineTo(px, cy + half + 18); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("y", (cx + px) / 2 - 3, cy + half + 34);

// x measurement
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(cx - 16, cy); ctx.lineTo(cx - 16, ey); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("x", cx - 28, (cy + ey) / 2);

var eps0 = 8.85e-12;
var f = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = f;

var R = p.R, z = p.z, sig = p.sigma * 1e-7;
var Esheet = sig / (2 * eps0);
var E = Esheet * (1 - z / Math.sqrt(z * z + R * R));

// layout: disk edge-on at the left, probe on the axis
var axY = H * 0.36;
var x0 = W * 0.16;
var mPerPx = 0.40 / (W * 0.70);
var diskPx = R / mPerPx;
if (diskPx > H * 0.30) diskPx = H * 0.30;

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0 - W * 0.08, axY); ctx.lineTo(W - 14, axY); ctx.stroke();

// stack of rings drawn as nested segments on the edge-on disk
var nRing = 7;
for (var i = 1; i <= nRing; i++) {
  var frac = i / nRing;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x0, axY - diskPx * frac); ctx.lineTo(x0, axY - diskPx * (frac - 0.55 / nRing));
  ctx.moveTo(x0, axY + diskPx * frac); ctx.lineTo(x0, axY + diskPx * (frac - 0.55 / nRing));
  ctx.stroke();
}
ctx.fillStyle = C.ink;
ctx.fillText("disk as a stack of rings, radius s, width ds", 8, axY - diskPx - 12);
ctx.fillText("R", x0 - 18, axY - diskPx + 4);

// probe
var px = x0 + z / mPerPx;
if (px > W - 30) px = W - 30;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, axY, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("z = " + z.toFixed(2) + " m", px - 20, axY + 34);

var arrowLen = 14 + 62 * (Esheet > 0 ? E / Esheet : 0);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(px, axY); ctx.lineTo(px + arrowLen, axY); ctx.stroke();
ctx.beginPath();
ctx.moveTo(px + arrowLen, axY); ctx.lineTo(px + arrowLen - 8, axY - 5); ctx.lineTo(px + arrowLen - 8, axY + 5);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();

// graph: E against z with the sheet value as the ceiling
var gy = H * 0.94, gx0 = 40, gx1 = W - 14, gtop = H * 0.60;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx0, gtop); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("E", gx0 - 18, gtop + 10);
ctx.fillText("z", gx1 - 10, gy + 16);

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(gx0, gtop + 6); ctx.lineTo(gx1, gtop + 6); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("sigma / 2 eps0", gx0 + 6, gtop + 18);

var zmax = 0.40;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 160; j++) {
  var zz = zmax * j / 160;
  var val = 1 - zz / Math.sqrt(zz * zz + R * R);
  var gxp = gx0 + (gx1 - gx0) * zz / zmax;
  var gyp = (gy) - (gy - gtop - 6) * val;
  if (j === 0) ctx.moveTo(gxp, gyp); else ctx.lineTo(gxp, gyp);
}
ctx.stroke();

var curx = gx0 + (gx1 - gx0) * Math.min(z, zmax) / zmax;
var cury = gy - (gy - gtop - 6) * (1 - z / Math.sqrt(z * z + R * R));
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(curx, cury, 4, 0, Math.PI * 2); ctx.fill();

out.note = "E = " + E.toFixed(0) + " N/C   |   sigma/2eps0 = " + Esheet.toFixed(0) +
  " N/C   |   ratio = " + (E / Esheet).toFixed(3);
